begin;
select no_plan();
insert into auth.users(id) values ('00000000-0000-0000-0000-000000005101');
insert into public.profiles(id,handle,name) values ('security-hidden-a','security_hidden_a','Hidden A'),('security-hidden-b','security_hidden_b','Hidden B');
insert into public.mutes(muter_id,muted_id) values('security-hidden-a','security-hidden-b');
