select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public' and p.proname like '%crew%' and has_function_privilege('anon',p.oid,'execute')),'no anonymous Crew function grants');
select ok(not has_function_privilege('authenticated','public.arena_crew_payload(public.arena_crews)','execute'),'Crew payload helper private');
select ok(not has_function_privilege('authenticated','public.arena_assert_crew_join_allowed(text)','execute'),'arbitrary membership eligibility helper private');
set local role anon;
select throws_ok($$select public.arena_actor_hidden('security-hidden-a','security-hidden-b')$$,'42501',null,'anonymous relationship oracle denied');
select throws_ok($$select public.explore_actor_hidden('security-hidden-a','security-hidden-b')$$,'42501',null,'anonymous Explore relationship oracle denied');
select throws_ok($$select public.vault_profiles_blocked('security-hidden-a','security-hidden-b')$$,'42501',null,'anonymous Vault relationship oracle denied');
select throws_ok($$select public.can_access_vault_drop('security-hidden-a','unavailable-drop')$$,'42501',null,'anonymous entitlement probing denied');
