select throws_ok($$select public.arena_message_room('unknown')$$,'42501',null,'guest private message lookup denied');
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000005101","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.arena_actor_hidden('security-hidden-a','security-hidden-b')$$,'42501',null,'authenticated arbitrary relationship oracle denied');
select throws_ok($$select public.explore_actor_hidden('security-hidden-a','security-hidden-b')$$,'42501',null,'authenticated Explore oracle denied');
select throws_ok($$select public.vault_profiles_blocked('security-hidden-a','security-hidden-b')$$,'42501',null,'authenticated Vault oracle denied');
select throws_ok($$select public.can_access_vault_drop('security-hidden-a','unavailable-drop')$$,'42501',null,'authenticated entitlement probing denied');
select throws_ok($$select public.can_access_course_lesson('security-hidden-a','unavailable-lesson')$$,'42501',null,'course entitlement probing denied');
select throws_ok($$select public.creator_ai_viewer_can_access('unavailable-creator','security-hidden-a')$$,'42501',null,'creator AI entitlement probing denied');
select throws_ok($$select public.creator_live_viewer_can_access('unavailable-session','security-hidden-a')$$,'42501',null,'creator live entitlement probing denied');
select throws_ok($$select public.vault_community_viewer_can_access('security-hidden-a','unavailable-community')$$,'42501',null,'community entitlement probing denied');
select throws_ok($$select public.arena_backup_reasons('security-hidden-a','security-hidden-b','unavailable-topic')$$,'42501',null,'backup relationship builder private');
select throws_ok($$select public.explore_vault_preview_rows('security-hidden-a',null,12)$$,'42501',null,'arbitrary-viewer preview builder private');
